{
  "items": [
    {
      "name": "IsPoly.below.sub",
      "module_name": "Mathlib.NumberTheory.Dioph",
      "kind": "constructor",
      "type": "∀ {α : Type u_1} {motive : (a : (α → ℕ) → ℤ) → IsPoly a → Prop} {f g : (α → ℕ) → ℤ} (a : IsPoly f) (a_1 : IsPoly g),\n  IsPoly.below a → motive f a → IsPoly.below a_1 → motive g a_1 → IsPoly.below ⋯"
    },
    {
      "name": "Poly.instSub",
      "module_name": "Mathlib.NumberTheory.Dioph",
      "kind": "instance",
      "type": "{α : Type u_1} → Sub (Poly α)"
    },
    {
      "name": "MvPolynomial.coeff_sub",
      "module_name": "Mathlib.Algebra.MvPolynomial.CommRing",
      "kind": "theorem",
      "type": "∀ {R : Type u} (σ : Type u_1) [inst : CommRing R] (m : σ →₀ ℕ) (p q : MvPolynomial σ R),\n  MvPolynomial.coeff m (p - q) = MvPolynomial.coeff m p - MvPolynomial.coeff m q"
    },
    {
      "name": "MvPolynomial.eval_sub",
      "module_name": "Mathlib.Algebra.MvPolynomial.CommRing",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommRing R] (p : MvPolynomial σ R) {q : MvPolynomial σ R} (f : σ → R),\n  (MvPolynomial.eval f) (p - q) = (MvPolynomial.eval f) p - (MvPolynomial.eval f) q"
    },
    {
      "name": "Poly.sub_apply",
      "module_name": "Mathlib.NumberTheory.Dioph",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} (f g : Poly α) (x : α → ℕ), (f - g) x = f x - g x"
    },
    {
      "name": "MvPolynomial.eval₂_sub",
      "module_name": "Mathlib.Algebra.MvPolynomial.CommRing",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} {σ : Type u_1} [inst : CommRing R] (p : MvPolynomial σ R) {q : MvPolynomial σ R}\n  [inst_1 : CommRing S] (f : R →+* S) (g : σ → S),\n  MvPolynomial.eval₂ f g (p - q) = MvPolynomial.eval₂ f g p - MvPolynomial.eval₂ f g q"
    }
  ]
}

